//! data.rs — static DATA tables for uniata.sys (UniATA IDE driver).
//! PURE DATA TRANSCRIPTION from the C headers (boot-critical):
//!   - BusMasterAdapters[]  : drivers/storage/ide/uniata/bm_devs.h
//!                            (macro PCI_DEV_HW_SPEC_BM in bm_devs_decl.h)
//!   - AtaCommands48[256]   : drivers/storage/ide/uniata/atacmd_map.h
//!   - AtaCommandFlags[256] : drivers/storage/ide/uniata/atacmd_map.h
//!
//! Compile path matches the C source: __REACTOS__ DEFINED (so #ifndef __REACTOS__
//! bodies are skipped, #else branches taken). Commented-out (/* */ and //) entries
//! are omitted, exactly as the C preprocessor would. The final BMLIST_TERMINATOR
//! entry is included.
//!
//! PCI_DEV_HW_SPEC_BM(idhi, idlo, rev, mode, name, flags) ->
//!   { nVendorId: 0x##idlo, nDeviceId: 0x##idhi, nRevId: rev,
//!     MaxTransferMode: mode, RaidFlags: flags, FullDevName: name }
//! (note the idlo->nVendorId, idhi->nDeviceId SWAP.)
#![allow(non_snake_case, non_camel_case_types, non_upper_case_globals, dead_code, unused_unsafe)]

use crate::types::*;
use ntkrnl_sys::ddk::{ULONG, UCHAR, PCSTR};

// BUSMASTER_CONTROLLER_INFORMATION_BASE holds a raw PCSTR (FullDevName), so it is not
// Sync. The C table is `static const` (read-only) and uniata is a single-threaded
// miniport; wrap it in a Sync newtype so it can live in a `pub static`. Index via
// `BusMasterAdapters.0[..]`.
#[repr(transparent)]
pub struct BmAdaptersTable<const N: usize>(pub [BUSMASTER_CONTROLLER_INFORMATION_BASE; N]);
unsafe impl<const N: usize> Sync for BmAdaptersTable<N> {}

